export const DASHBOARD="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>OUCU | Contact Center</title><meta name=\"description\" content=\"OUCU Financial contact center supervisor dashboard. Demonstration data for Webex Contact Center.\"><link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%23007580'/%3E%3Ctext x='16' y='23' text-anchor='middle' font-size='23' font-family='Arial' fill='white'%3EO%3C/text%3E%3C/svg%3E\"><style>\n:root{--teal:#0b8295;--deep:#004c55;--green:#4ba874;--ink:#16383d;--muted:#60777b;--line:#deeaec;--bg:#f2f7f8;--orange:#ab621e}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:16px/1.45 'Segoe UI',Arial,sans-serif}button,select{font:inherit}button{cursor:pointer}header{height:94px;display:flex;align-items:center;justify-content:space-between;padding:0 36px;background:white;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:26px}.logo{width:178px;height:62px;object-fit:contain}.brandtext{border-left:1px solid var(--line);padding-left:26px}.brandtext strong{display:block;font-size:17px}.brandtext span{color:var(--muted);font-size:14px}.headright{display:flex;align-items:center;gap:20px}.sample{background:#edf5df;color:#426825;padding:7px 12px;border-radius:5px;font-size:14px;font-weight:600}.clock{font-size:22px;font-weight:650}.clock small{display:block;font-size:12px;color:var(--muted);font-weight:400;text-align:right}main{max-width:1600px;margin:auto;padding:30px 36px}.intro{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:2px;color:var(--teal)}h1{font-size:30px;margin:4px 0;font-weight:650;letter-spacing:-.8px}.intro p{margin:0;color:var(--muted);font-size:14px}.controls{display:flex;gap:10px;align-items:center}select,button{background:white;border:1px solid #cddde0;border-radius:6px;padding:10px 14px;color:var(--ink)}button:hover{background:#e8f2f3}button:focus-visible,select:focus-visible{outline:3px solid var(--green);outline-offset:2px}.strip{background:var(--deep);color:white;padding:16px 22px;border-radius:9px;display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.strip strong{font-size:16px}.strip span{font-size:14px;color:#c7e5e7}.strip .target{color:#cef1a9}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;margin-bottom:22px}.kpi{background:white;border:1px solid var(--line);padding:20px 22px;border-radius:9px;position:relative;overflow:hidden}.kpi:first-child{border-top:4px solid var(--green);padding-top:17px}.label{font-size:14px;color:var(--muted);font-weight:600}.value{font-size:40px;letter-spacing:-1.5px;font-weight:650;margin:6px 0}.value small{font-size:19px;letter-spacing:0;font-weight:400;color:var(--muted)}.foot{font-size:13px;color:var(--muted)}.good{color:#467e2c;font-weight:600}.spark{position:absolute;right:16px;bottom:22px;width:90px;height:28px}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,1fr);gap:22px}.panel{background:white;border:1px solid var(--line);border-radius:9px;overflow:hidden}.panelhead{padding:20px 22px 12px;display:flex;align-items:center;justify-content:space-between;gap:12px}h2{font-size:18px;font-weight:650;margin:0}.meta{color:var(--muted);font-size:13px}.legend{display:flex;gap:15px;font-size:12px;color:var(--muted)}.legend i{display:inline-block;width:9px;height:9px;margin-right:5px;background:var(--teal);border-radius:2px}.legend i.lime{background:var(--green)}.chart{padding:0 20px 14px}.chart svg{width:100%;height:218px;overflow:visible}.chart text{font-family:inherit;font-size:12px;fill:var(--muted)}.queuewrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}th{font-size:12px;color:var(--muted);font-weight:600;background:#f7fafb;padding:11px 20px;white-space:nowrap}td{padding:15px 20px;border-top:1px solid #edf2f3;white-space:nowrap}td:first-child{font-weight:600}.badge{display:inline-block;padding:4px 9px;border-radius:5px;font-size:12px;font-weight:600;background:#edf5e7;color:#41772d}.badge.watch{background:#fff3df;color:#976020}.queue-bottom{display:flex;justify-content:space-between;padding:15px 20px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.agents{margin-top:22px}.agentgrid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;padding:8px 22px 22px}.agent{border:1px solid var(--line);border-radius:7px;padding:15px;min-width:0}.person{display:flex;align-items:center;gap:9px;margin-bottom:12px}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#e4f0f1;color:var(--teal);font-size:12px;font-weight:700;flex-shrink:0}.name{font-size:14px;font-weight:600}.agent .queue{font-size:12px;color:var(--muted);margin-top:6px}.status{font-size:13px;font-weight:600;color:var(--teal)}.status:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:7px}.available{color:#527e31}.wrap{color:#9c701c}.away{color:#7b8589}.timer{font-size:19px;font-variant-numeric:tabular-nums;margin-top:8px}.summary{display:flex;gap:16px;font-size:13px;color:var(--muted)}.bottom{display:flex;justify-content:space-between;gap:20px;margin-top:17px;font-size:12px;color:var(--muted)}.bottom a{color:var(--teal)}.attention{display:flex;gap:12px;align-items:flex-start;padding:14px 20px;background:#fff8ed;border-top:1px solid #f0e3cc;font-size:13px}.attention b{color:#986221}.gauge{display:flex;gap:22px;align-items:center;padding:8px 22px 24px}.gauge svg{width:138px;height:138px;flex-shrink:0}.gauge h3{font-size:24px;margin:0 0 4px}.gauge p{font-size:14px;color:var(--muted);margin:0}.service{margin-top:22px}.progress{height:7px;background:#eaf0f1;border-radius:8px;margin-top:12px;overflow:hidden}.progress span{display:block;background:var(--green);height:100%;width:91%}.metricrow{display:flex;justify-content:space-between;font-size:14px;padding:0 22px 20px}.metricrow strong{font-size:16px}.rightstack{display:flex;flex-direction:column;gap:22px}.notebox{padding:16px 22px;background:#eaf3f4;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}@media(min-width:1450px){.chart svg{height:248px}}@media(max-width:1100px){.agentgrid{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:1fr}.rightstack{display:grid;grid-template-columns:1fr 1fr}.kpis{gap:10px;grid-template-columns:repeat(3,1fr)}.kpi{padding:16px}.spark{display:none}}@media(max-width:700px){header{padding:12px 18px;height:auto}.brand{gap:12px}.logo{width:120px}.brandtext{display:none}.headright{gap:10px}.clock{font-size:17px}.sample{font-size:12px}main{padding:22px 16px}.intro{align-items:flex-start;gap:16px;flex-direction:column}.controls{width:100%}select{flex:1;min-width:0}.kpis{grid-template-columns:repeat(2,1fr)}.value{font-size:32px}.strip{gap:12px;align-items:flex-start;flex-direction:column}.rightstack{display:flex}.agentgrid{grid-template-columns:repeat(2,1fr);padding:8px 14px 16px}.summary{gap:8px;flex-wrap:wrap}.panelhead{align-items:flex-start;flex-direction:column}.bottom{flex-direction:column;gap:6px}.gauge{gap:14px}.gauge svg{width:115px}}\n</style></head><body>\n<header><div class=\"brand\"><img class=\"logo\" src=\"logo.png\" alt=\"OUCU Financial\"><div class=\"brandtext\"><strong>Contact Center</strong><span>Supervisor workspace</span></div></div><div class=\"headright\"><a id=\"webex-link\" href=\"/settings/webex\" target=\"_top\" style=\"font-size:14px;color:var(--teal);text-decoration:none\">Connect Webex</a><span class=\"sample\">Sample data</span><div class=\"clock\" id=\"clock\">—<small>Eastern time</small></div></div></header>\n<main><section class=\"intro\"><div><div class=\"eyebrow\">MEMBER EXPERIENCE</div><h1>Today at a glance</h1><p id=\"date\">Webex Contact Center · Daily overview</p></div><div class=\"controls\"><label for=\"queue\" class=\"label\">Queue</label><select id=\"queue\"><option value=\"all\">All queues</option><option value=\"Member Services\">Member Services</option><option value=\"Lending\">Lending</option><option value=\"Digital Banking\">Digital Banking</option></select><button id=\"fullscreen\" aria-label=\"Toggle fullscreen\">Fullscreen</button></div></section>\n<div class=\"strip\"><div><strong id=\"headline\">Member service is on track</strong><br><span id=\"subline\">3 queues · 6 agents signed in · 2 members waiting</span></div><span class=\"target\">Service level target: 80% within 30s</span></div>\n<section class=\"kpis\" aria-label=\"Key metrics\"><article class=\"kpi\"><div class=\"label\">Service level</div><div class=\"value\" id=\"sl\">91.4<small>%</small></div><div class=\"foot\"><span class=\"good\">Above target</span> · 30-second threshold</div></article><article class=\"kpi\"><div class=\"label\">Calls handled</div><div class=\"value\" id=\"handled\">248</div><div class=\"foot\">Of <b id=\"offered\">262</b> offered today</div><svg class=\"spark\" viewBox=\"0 0 90 28\"><path d=\"M0 26L10 22L20 24L30 15L40 17L50 11L60 14L70 6L80 8L90 1\" fill=\"none\" stroke=\"#0b8295\" stroke-width=\"2\"/></svg></article><article class=\"kpi\"><div class=\"label\">Average speed of answer</div><div class=\"value\" id=\"asa\">18<small> sec</small></div><div class=\"foot\">Time before an agent answers</div></article><article class=\"kpi\"><div class=\"label\">Abandon rate</div><div class=\"value\" id=\"abandon\">3.8<small>%</small></div><div class=\"foot\"><b id=\"abandoned\">10</b> callers left before answer</div></article><article class=\"kpi\"><div class=\"label\">First contact resolution</div><div class=\"value\" id=\"fcr\">85.1<small>%</small></div><div class=\"foot\"><b id=\"resolved\">211</b> of <span id=\"fcr-total\">248</span> resolved on first contact</div></article></section>\n<div class=\"grid\"><div><section class=\"panel\"><div class=\"panelhead\"><div><h2>Call volume</h2><span class=\"meta\">Today's hourly distribution · sample</span></div><div class=\"legend\"><span><i></i>Handled</span><span><i class=\"lime\"></i>Abandoned</span></div></div><div class=\"chart\" id=\"chart\"></div></section><section class=\"panel service\"><div class=\"panelhead\"><h2>Queue health</h2><span class=\"meta\">Current snapshot</span></div><div class=\"queuewrap\"><table><thead><tr><th>Queue</th><th>Waiting</th><th>Longest wait</th><th>Service level</th><th>Health</th></tr></thead><tbody id=\"queues\"></tbody></table></div><div class=\"attention\" id=\"attention\"><b>Needs attention</b><span>Digital Banking has the longest wait at 01:12. Consider shifting an available agent.</span></div><div class=\"queue-bottom\"><span>Voice queues</span><span>Demonstration snapshot</span></div></section></div><div class=\"rightstack\"><section class=\"panel\"><div class=\"panelhead\"><h2>Agent availability</h2><span class=\"meta\">6 signed in</span></div><div class=\"gauge\"><svg viewBox=\"0 0 140 140\" aria-label=\"2 available, 2 on call, 1 wrap-up, 1 away\"><circle cx=\"70\" cy=\"70\" r=\"53\" fill=\"none\" stroke=\"#e9eff0\" stroke-width=\"12\"/><circle cx=\"70\" cy=\"70\" r=\"53\" fill=\"none\" stroke=\"#0b8295\" stroke-width=\"12\" stroke-dasharray=\"111 222\" transform=\"rotate(-90 70 70)\"/><circle cx=\"70\" cy=\"70\" r=\"53\" fill=\"none\" stroke=\"#4ba874\" stroke-width=\"12\" stroke-dasharray=\"111 222\" stroke-dashoffset=\"-111\" transform=\"rotate(-90 70 70)\"/><circle cx=\"70\" cy=\"70\" r=\"53\" fill=\"none\" stroke=\"#d8b256\" stroke-width=\"12\" stroke-dasharray=\"55.5 277.5\" stroke-dashoffset=\"-222\" transform=\"rotate(-90 70 70)\"/><text x=\"70\" y=\"70\" text-anchor=\"middle\" font-size=\"33\" font-family=\"Segoe UI,Arial\" fill=\"#16383d\" font-weight=\"650\">6</text><text x=\"70\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" fill=\"#60777b\">signed in</text></svg><div><h3>2 available</h3><p>Ready for the next member</p><div class=\"progress\"><span style=\"width:33.33%\"></span></div></div></div><div class=\"metricrow\"><span>On call</span><strong>2</strong></div><div class=\"metricrow\"><span>Wrap-up</span><strong>1</strong></div><div class=\"metricrow\"><span>Away</span><strong>1</strong></div><div class=\"notebox\">Agent availability shows all queues.</div></section><section class=\"panel\"><div class=\"panelhead\"><h2>Conversation time</h2><span class=\"meta\">Average per handled call</span></div><div style=\"padding:0 22px 20px\"><div class=\"value\">04:32</div><div class=\"foot\">Average handle time</div><div style=\"display:flex;height:9px;margin:22px 0;border-radius:8px;overflow:hidden\"><span style=\"background:var(--teal);width:74%\"></span><span style=\"background:#a5cbd0;width:8%\"></span><span style=\"background:var(--green);width:18%\"></span></div></div><div class=\"metricrow\"><span>Talk time</span><strong>03:21</strong></div><div class=\"metricrow\"><span>Hold time</span><strong>00:22</strong></div><div class=\"metricrow\"><span>Wrap-up time</span><strong>00:49</strong></div><div class=\"notebox\">Conversation time shows all queues.</div></section></div></div>\n<section class=\"panel agents\"><div class=\"panelhead\"><h2>Agent status</h2><div class=\"summary\"><span>2 available</span><span>2 on call</span><span>1 wrap-up</span><span>1 away</span></div></div><div class=\"agentgrid\" id=\"agents\"></div></section><footer class=\"bottom\"><span>Demo environment · Fictional agents and metrics · Webex data connection pending</span><span>Brand reference: <a href=\"https://www.oucu.org/\" target=\"_blank\" rel=\"noopener\">OUCU Financial</a></span></footer></main>\n<script>\nconst rows=[{name:'Member Services',waiting:1,wait:'00:24',sl:94.2,handled:156,offered:162,asa:14,aband:4,rate:2.5,resolved:136},{name:'Lending',waiting:0,wait:'00:00',sl:90.0,handled:54,offered:58,asa:21,aband:2,rate:3.4,resolved:46},{name:'Digital Banking',waiting:1,wait:'01:12',sl:82.1,handled:38,offered:42,asa:37,aband:4,rate:9.5,resolved:29}];\nconst agents=[['AT','Alex Taylor','Available','available','06:14','Member Services'],['JM','Jordan Miller','On call','','03:42','Member Services'],['SC','Sam Carter','Available','available','02:08','Lending'],['MR','Morgan Reed','On call','','05:17','Digital Banking'],['CP','Casey Parker','Wrap-up','wrap','00:38','Member Services'],['RL','Riley Lee','Away · Break','away','08:21','Lending']];\ndocument.getElementById('agents').innerHTML=agents.map(a=>`<article class=\"agent\"><div class=\"person\"><div class=\"avatar\">${a[0]}</div><div class=\"name\">${a[1]}</div></div><div class=\"status ${a[3]}\">${a[2]}</div><div class=\"timer\">${a[4]}</div><div class=\"queue\">${a[5]}</div></article>`).join('');\nfunction render(){const q=document.getElementById('queue').value;const selected=rows.filter(r=>q==='all'||r.name===q);document.getElementById('queues').innerHTML=selected.map(r=>`<tr><td>${r.name}</td><td>${r.waiting}</td><td>${r.wait}</td><td>${r.sl.toFixed(1)}%</td><td><span class=\"badge ${r.name==='Digital Banking'?'watch':''}\">${r.name==='Digital Banking'?'Needs attention':'Healthy'}</span></td></tr>`).join('');const r=q==='all'?{sl:91.4,handled:248,offered:262,asa:18,aband:10,rate:3.8,resolved:211}:selected[0];for(const [id,value] of Object.entries({sl:`${r.sl.toFixed(1)}<small>%</small>`,handled:r.handled,offered:r.offered,asa:`${r.asa}<small> sec</small>`,abandon:`${r.rate}<small>%</small>`,abandoned:r.aband,fcr:`${(r.resolved/r.handled*100).toFixed(1)}<small>%</small>`,resolved:r.resolved,'fcr-total':r.handled})){document.getElementById(id).innerHTML=value}document.getElementById('headline').textContent=q==='Digital Banking'?'Digital Banking needs attention':'Member service is on track';document.getElementById('subline').textContent=q==='all'?'3 queues · 6 agents signed in · 2 members waiting':`${q} · ${selected[0].waiting} member${selected[0].waiting===1?'':'s'} waiting`;document.getElementById('attention').hidden=q==='Member Services'||q==='Lending';const vals=[20,36,43,33,27,38,31,20];const factor=q==='all'?1:r.handled/248;let svg='<svg viewBox=\"0 0 690 210\" role=\"img\" aria-label=\"Sample hourly handled and abandoned call counts\">';for(let i=0;i<4;i++){const y=170-i*45;svg+=`<line x1=\"38\" y1=\"${y}\" x2=\"678\" y2=\"${y}\" stroke=\"#e5eef0\"/><text x=\"25\" y=\"${y+4}\" text-anchor=\"end\">${i*15}</text>`}vals.forEach((v,i)=>{const h=v*factor*3,ab=[1,2,1,1,1,2,1,1][i]*factor*3,x=60+i*78;svg+=`<rect x=\"${x}\" y=\"${170-h}\" width=\"32\" height=\"${h}\" rx=\"3\" fill=\"#0b8295\"><title>${9+i}:00 · ${Math.round(v*factor)} handled</title></rect><rect x=\"${x+34}\" y=\"${170-ab}\" width=\"12\" height=\"${ab}\" rx=\"2\" fill=\"#4ba874\"/><text x=\"${x+22}\" y=\"195\" text-anchor=\"middle\">${String(9+i).padStart(2,'0')}:00</text>`});document.getElementById('chart').innerHTML=svg+'</svg>'}\ndocument.getElementById('queue').addEventListener('change',render);render();function clock(){const d=new Date();document.getElementById('clock').innerHTML=d.toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'})+'<small>Eastern time</small>';document.getElementById('date').textContent=d.toLocaleDateString('en-US',{timeZone:'America/New_York',weekday:'long',month:'long',day:'numeric',year:'numeric'})+' · Webex Contact Center'}clock();setInterval(clock,30000);document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){document.getElementById('fullscreen').textContent='Fullscreen unavailable'}};document.addEventListener('fullscreenchange',()=>document.getElementById('fullscreen').textContent=document.fullscreenElement?'Exit fullscreen':'Fullscreen');\nif(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'select_queue',description:'Select a queue and update the demonstration dashboard metrics.',inputSchema:{type:'object',properties:{queue:{type:'string',enum:['all','Member Services','Lending','Digital Banking']}},required:['queue'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['all',...rows.map(r=>r.name)].includes(input.queue))throw new Error('Unknown queue');document.getElementById('queue').value=input.queue;render();return{selectedQueue:input.queue,dataMode:'sample'}}})).catch(()=>{});}\nfetch('/api/webex/status').then(r=>r.ok?r.json():null).then(s=>{if(s?.authorized)document.getElementById('webex-link').textContent=s.reportingVerified?'Webex connected · Sample metrics':'Webex authorized · Verify access'}).catch(()=>{});\n</script></body></html>\n";
